const enc=new TextEncoder(),dec=new TextDecoder();
function b64(bytes){let s='';for(const x of bytes)s+=String.fromCharCode(x);return btoa(s)}
function fromB64(s){const raw=atob(s);return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function cryptoKey(secret){return crypto.subtle.importKey('raw',fromB64(secret),{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function encryptSecret(value,secret){const key=await cryptoKey(secret),iv=crypto.getRandomValues(new Uint8Array(12)),data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,enc.encode(value));return{cipher:b64(new Uint8Array(data)),iv:b64(iv)}}
async function decryptSecret(cipher,iv,secret){if(!cipher||!iv)return'';const key=await cryptoKey(secret),data=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(iv)},key,fromB64(cipher));return dec.decode(data)}
async function readConfig(env){const c=(await env.META_CONFIG.get('config','json'))||{apiVersion:'v23.0',selectedAccountIds:[]};return{...c,prospectionPipelineId:'78790',closerPipelineId:'84566'}}
// Tokens: secrets do Worker (META_ACCESS_TOKEN / PIPERUN_TOKEN) têm prioridade; senão, o token salvo criptografado no KV pela tela de Configurações.
async function metaTokenOf(env,stored){return String(env.META_ACCESS_TOKEN||'').trim()||await decryptSecret(stored.tokenCipher,stored.tokenIv,env.TOKEN_KEY)}
async function pipeTokenOf(env,stored){return String(env.PIPERUN_TOKEN||'').trim()||await decryptSecret(stored.pipeRunTokenCipher,stored.pipeRunTokenIv,env.TOKEN_KEY)}
function hasMetaToken(env,stored){return !!(String(env.META_ACCESS_TOKEN||'').trim()||stored.tokenCipher)}
function hasPipeToken(env,stored){return !!(String(env.PIPERUN_TOKEN||'').trim()||stored.pipeRunTokenCipher)}
async function saveConfig(env,cfg){await env.META_CONFIG.put('config',JSON.stringify(cfg))}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}})}
async function reqJson(req){try{return await req.json()}catch{return{}}}
function actionValue(actions,keys){if(!Array.isArray(actions))return 0;for(const k of keys){const f=actions.find(a=>a.action_type===k);if(f)return Number(f.value||0)}return 0}
async function mapLimit(items,limit,fn){const out=new Array(items.length),workers=Array.from({length:Math.min(limit,items.length)},async(_,w)=>{for(let i=w;i<items.length;i+=limit)out[i]=await fn(items[i],i)});await Promise.all(workers);return out}
async function graph(pathname,params,cfg){const u=new URL(`https://graph.facebook.com/${cfg.apiVersion||'v23.0'}/${String(pathname||'').replace(/^\//,'')}`);for(const[k,v]of Object.entries(params||{})){if(v!==undefined&&v!==null&&v!=='')u.searchParams.set(k,typeof v==='object'?JSON.stringify(v):String(v))}u.searchParams.set('access_token',cfg.accessToken);const r=await fetch(u);const j=await r.json();if(!r.ok||j.error){const e=new Error(j?.error?.message||`Meta API HTTP ${r.status}`);e.meta=j?.error;throw e}return j}
async function graphAll(pathname,params,cfg,maxPages=100){let first=await graph(pathname,params,cfg),data=[...(first.data||[])],next=first.paging?.next,pages=1;while(next&&pages<maxPages){const r=await fetch(next),j=await r.json();if(!r.ok||j.error)break;data.push(...(j.data||[]));next=j.paging?.next;pages++}return data}
async function getMetaConfig(env){const stored=await readConfig(env),accessToken=await metaTokenOf(env,stored);if(!accessToken)throw new Error('Configure primeiro o Access Token da Meta.');return{...stored,accessToken}}
async function getPipeToken(env){const stored=await readConfig(env),token=await pipeTokenOf(env,stored);if(!token)throw new Error('Conecte primeiro o token do PipeRun.');return token}
