async function getCreatives(accountId,cfg){const fields='id,name,status,effective_status,created_time,creative{id,name,title,body,thumbnail_url,object_story_spec{link_data{link},video_data{call_to_action{value{link}}}},asset_feed_spec{link_urls{website_url}}}';return graphAll(`${accountId}/ads`,{fields,limit:250},cfg,100)}
async function getCreativesByIds(adIds,cfg){const fields='id,name,status,effective_status,created_time,creative{id,name,title,body,thumbnail_url,object_story_spec{link_data{link},video_data{call_to_action{value{link}}}},asset_feed_spec{link_urls{website_url}}}';const ids=[...new Set((adIds||[]).map(String).filter(Boolean))],batches=[];for(let i=0;i<ids.length;i+=40)batches.push(ids.slice(i,i+40));const parts=await mapLimit(batches,2,async part=>{const u=new URL(`https://graph.facebook.com/${cfg.apiVersion||'v23.0'}`),batch=part.map(id=>({method:'GET',relative_url:`${id}?fields=${encodeURIComponent(fields)}`})),body=new URLSearchParams({access_token:cfg.accessToken,batch:JSON.stringify(batch),include_headers:'false'}),r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),j=await r.json();if(!r.ok||!Array.isArray(j)){const e=new Error(j?.error?.message||`Meta batch HTTP ${r.status}`);e.meta=j?.error;throw e}const out=[],errs=[];for(const item of j){if(Number(item?.code)>=200&&Number(item?.code)<300&&item?.body){try{const x=JSON.parse(item.body);if(x?.id)out.push(x)}catch{}}else if(item?.body){try{const x=JSON.parse(item.body);if(x?.error?.message)errs.push(x.error.message)}catch{}}}if(!out.length&&part.length&&errs.length)throw new Error(errs[0]);return out});return parts.flat()}
function normalizeAd(r){const leads=actionValue(r.actions,['lead','onsite_conversion.lead_grouped','offsite_conversion.fb_pixel_lead']),lpv=actionValue(r.actions,['landing_page_view']),views3=actionValue(r.video_play_actions,['video_view']),v25=actionValue(r.video_p25_watched_actions,['video_view']),v50=actionValue(r.video_p50_watched_actions,['video_view']),v75=actionValue(r.video_p75_watched_actions,['video_view']),v95=actionValue(r.video_p95_watched_actions,['video_view']),v100=actionValue(r.video_p100_watched_actions,['video_view']),thru=actionValue(r.video_thruplay_watched_actions,['video_view']),out=Array.isArray(r.outbound_clicks)?Number(r.outbound_clicks[0]?.value||0):Number(r.outbound_clicks||0);return{...r,spend:Number(r.spend||0),impressions:Number(r.impressions||0),reach:Number(r.reach||0),frequency:Number(r.frequency||0),clicks:Number(r.clicks||0),inline_link_clicks:Number(r.inline_link_clicks||0),outbound_clicks:out,ctr:Number(r.ctr||0),cpc:Number(r.cpc||0),cpm:Number(r.cpm||0),leads,lpv,views3,v25,v50,v75,v95,v100,thru}}
function normalizeDaily(r){return{...r,spend:Number(r.spend||0),impressions:Number(r.impressions||0),reach:Number(r.reach||0),clicks:Number(r.clicks||0),inline_link_clicks:Number(r.inline_link_clicks||0),leads:actionValue(r.actions,['lead','onsite_conversion.lead_grouped','offsite_conversion.fb_pixel_lead']),lpv:actionValue(r.actions,['landing_page_view'])}}
function aggregateDaily(rows){const map=new Map();for(const r of(rows||[])){const day=String(r.date_start||r.date_stop||'');if(!day)continue;if(!map.has(day))map.set(day,{account_id:r.account_id||'',account_name:r.account_name||'',date_start:day,date_stop:day,spend:0,impressions:0,reach:0,clicks:0,inline_link_clicks:0,leads:0,lpv:0,ctr:0,cpc:0,cpm:0});const x=map.get(day);for(const k of['spend','impressions','reach','clicks','inline_link_clicks','leads','lpv'])x[k]+=Number(r[k]||0)}for(const x of map.values()){x.ctr=x.impressions?100*x.clicks/x.impressions:0;x.cpc=x.clicks?x.spend/x.clicks:0;x.cpm=x.impressions?1000*x.spend/x.impressions:0}return[...map.values()].sort((a,b)=>a.date_start.localeCompare(b.date_start))}
async function saveMetaPeriod(env,accountId,since,until,ads,daily){const now=new Date().toISOString();await env.DB.prepare(`INSERT INTO meta_account_period(account_id,since_date,until_date,ads_json,daily_json,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(account_id,since_date,until_date) DO UPDATE SET ads_json=excluded.ads_json,daily_json=excluded.daily_json,updated_at=excluded.updated_at`).bind(String(accountId),since,until,JSON.stringify(ads||[]),JSON.stringify(daily||[]),now).run();const rows=(daily||[]).filter(r=>r.date_start||r.date_stop);for(let i=0;i<rows.length;i+=50){const part=rows.slice(i,i+50),stmts=part.map(r=>env.DB.prepare(`INSERT INTO meta_daily_fact(account_id,day,spend,impressions,clicks,lpv,leads,updated_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(account_id,day) DO UPDATE SET spend=excluded.spend,impressions=excluded.impressions,clicks=excluded.clicks,lpv=excluded.lpv,leads=excluded.leads,updated_at=excluded.updated_at WHERE meta_daily_fact.spend IS NOT excluded.spend OR meta_daily_fact.leads IS NOT excluded.leads OR meta_daily_fact.impressions IS NOT excluded.impressions OR meta_daily_fact.clicks IS NOT excluded.clicks OR meta_daily_fact.lpv IS NOT excluded.lpv`).bind(String(accountId),String(r.date_start||r.date_stop),Number(r.spend||0),Number(r.impressions||0),Number(r.inline_link_clicks||r.clicks||0),Number(r.lpv||0),Number(r.leads||0),now));if(stmts.length)await env.DB.batch(stmts)}}
async function saveCreativeCache(env,ads){if(!Array.isArray(ads)||!ads.length)return;const now=new Date().toISOString();for(let i=0;i<ads.length;i+=50){const part=ads.slice(i,i+50),stmts=part.filter(a=>a?.id&&a?.creative).map(a=>env.DB.prepare(`INSERT INTO creative_cache(ad_id,creative_json,updated_at) VALUES(?,?,?) ON CONFLICT(ad_id) DO UPDATE SET creative_json=excluded.creative_json,updated_at=excluded.updated_at WHERE creative_cache.creative_json IS NOT excluded.creative_json`).bind(String(a.id),JSON.stringify({...a.creative,_ad_created_time:a.created_time||'',_ad_status:a.effective_status||a.status||'',_ad_name:a.name||''}),now));if(stmts.length)await env.DB.batch(stmts)}}
async function saveCrmPeriod(env,since,until,payload){const now=new Date().toISOString();await env.DB.prepare(`INSERT INTO crm_period(since_date,until_date,payload_json,updated_at) VALUES(?,?,?,?) ON CONFLICT(since_date,until_date) DO UPDATE SET payload_json=excluded.payload_json,updated_at=excluded.updated_at`).bind(since,until,JSON.stringify(payload||{}),now).run();const rows=Array.isArray(payload?.daily)?payload.daily:[];for(let i=0;i<rows.length;i+=50){const part=rows.slice(i,i+50),stmts=part.map(r=>env.DB.prepare(`INSERT INTO crm_daily_fact(day,opportunities,meetings,no_shows,wins,revenue,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(day) DO UPDATE SET opportunities=excluded.opportunities,meetings=excluded.meetings,no_shows=excluded.no_shows,wins=excluded.wins,revenue=excluded.revenue,updated_at=excluded.updated_at`).bind(String(r.day),Number(r.opportunities||0),Number(r.meetings||0),Number(r.noShows||0),Number(r.wins||0),Number(r.revenue||0),now));if(stmts.length)await env.DB.batch(stmts)}}
function parseJsonSafe(v,fallback){try{return JSON.parse(v)}catch{return fallback}}
// Soma qualquer período dentro dos dias quentes a partir de meta_ad_day (anúncio×dia) e meta_daily_fact (conta×dia).
async function loadPersistentCache(env,ids,since,until,opts={}){if(!Array.isArray(ids)||!ids.length)return{ads:[],daily:[],creatives:[],crm:null,cachedAccounts:0,totalAccounts:0,lastUpdated:null};const ph=ids.map(()=>'?').join(','),times=[];
let ads=((await env.DB.prepare(`SELECT account_id,MAX(account_name) account_name,MAX(campaign_id) campaign_id,MAX(campaign_name) campaign_name,MAX(adset_id) adset_id,MAX(adset_name) adset_name,ad_id,MAX(ad_name) ad_name,SUM(spend) spend,SUM(impressions) impressions,SUM(reach) reach,SUM(clicks) clicks,SUM(inline_link_clicks) inline_link_clicks,SUM(outbound_clicks) outbound_clicks,SUM(lpv) lpv,SUM(leads) leads,SUM(views3) views3,SUM(v25) v25,SUM(v50) v50,SUM(v75) v75,SUM(v95) v95,SUM(v100) v100,SUM(thru) thru,MAX(updated_at) updated_at FROM meta_ad_day WHERE day BETWEEN ? AND ? AND account_id IN (${ph}) GROUP BY ad_id,account_id`).bind(since,until,...ids).all()).results||[]).map(a=>({...a,date_start:since,date_stop:until,ctr:a.impressions?100*a.clicks/a.impressions:0,cpc:a.clicks?a.spend/a.clicks:0,cpm:a.impressions?1000*a.spend/a.impressions:0,frequency:a.reach?a.impressions/a.reach:0}));
ads.forEach(a=>a.updated_at&&times.push(a.updated_at));
const daily=((await env.DB.prepare(`SELECT account_id,day date_start,day date_stop,spend,impressions,clicks,clicks inline_link_clicks,lpv,leads,updated_at FROM meta_daily_fact WHERE day BETWEEN ? AND ? AND account_id IN (${ph}) ORDER BY day`).bind(since,until,...ids).all()).results||[]);
// Transição: enquanto meta_ad_day não tiver dados, usa o agregado antigo da janela exata.
let res={results:[]};const cover=await env.DB.prepare(`SELECT MIN(day) m FROM meta_ad_day`).first();if(!opts.light&&(!ads.length||!cover?.m||cover.m>since)){ads=[];res=await env.DB.prepare(`SELECT account_id,ads_json,updated_at FROM meta_account_period WHERE account_id IN (${ph}) AND until_date>=? AND since_date<=? ORDER BY until_date DESC,updated_at DESC`).bind(...ids,brDate(-2),brDate(-27)).all();const seen=new Set();res.results=(res.results||[]).filter(r=>!seen.has(r.account_id)&&seen.add(r.account_id));for(const row of res.results){ads.push(...parseJsonSafe(row.ads_json,[]));if(row.updated_at)times.push(row.updated_at)}}
const synced=await env.DB.prepare(`SELECT value FROM sync_state WHERE key='meta_synced_at'`).first();if(synced?.value)times.push(synced.value);const adIds=opts.light&&!opts.creatives?[]:[...new Set(ads.map(a=>String(a.ad_id||'')).filter(Boolean))],creatives=[];for(let i=0;i<adIds.length;i+=90){const part=adIds.slice(i,i+90),p2=part.map(()=>'?').join(','),cr=await env.DB.prepare(`SELECT ad_id,creative_json,updated_at FROM creative_cache WHERE ad_id IN (${p2})`).bind(...part).all();for(const row of(cr.results||[])){creatives.push({id:String(row.ad_id),creative:parseJsonSafe(row.creative_json,{})});if(row.updated_at)times.push(row.updated_at)}}const crm=await crmFromStore(env,since,until,{light:!!opts.light});if(crm.meta.syncedAt)times.push(crm.meta.syncedAt);times.sort();return{ads,daily,creatives,crm,cachedAccounts:new Set(ads.map(a=>String(a.account_id))).size||(res.results||[]).length,totalAccounts:ids.length,lastUpdated:times.length?times[times.length-1]:null,hotSince:brDate(-29)}}
async function pipeGet(pathname,params,token){const u=new URL(`https://api.pipe.run/v1/${String(pathname||'').replace(/^\//,'')}`);for(const[k,v]of Object.entries(params||{})){if(v!==undefined&&v!==null&&v!=='')u.searchParams.set(k,String(v))}const r=await fetch(u,{headers:{accept:'application/json',token}}),j=await r.json().catch(()=>({}));if(!r.ok||j.success===false){const e=new Error(j?.message||j?.error||`PipeRun API HTTP ${r.status}`);e.pipe=j;throw e}return j}
async function pipeAll(pathname,params,token,maxPages=100){let page=1,cursor='',pages=0,data=[];while(pages<maxPages){const req={show:200,...params};if(cursor)req.cursor=cursor;else req.page=page;const j=await pipeGet(pathname,req,token),chunk=Array.isArray(j.data)?j.data:Array.isArray(j?.data?.data)?j.data.data:Array.isArray(j?.data?.items)?j.data.items:[];data.push(...chunk);const meta=j?.meta||j?.data?.meta||{},cursorNext=meta?.cursor?.next||j?.cursor?.next||'',current=Number(meta?.current_page||page||1),total=Number(meta?.total_pages||current||1),linkNext=meta?.links?.next||j?.links?.next||'';pages++;if(cursorNext){cursor=cursorNext;continue}cursor='';if(current<total){page=current+1;continue}if(linkNext){try{const np=Number(new URL(linkNext).searchParams.get('page'));if(np&&np!==page){page=np;continue}}catch{}}break}return data}
function dealValue(d){return Number(d?.value??d?.value_products_services??d?.items_value??d?.total_value??0)||0}
function ownerId(x){return String(x?.owner_id??x?.user_id??x?.owner?.id??'')}
function dealId(x){return String(x?.deal_id??x?.deal?.id??x?.id??'')}
