function isMeetingType(t){const n=meetingTypeName(t);if(/(pr[eé][- ]?reuni|disponibilidade|lembrete|confirma|follow[- ]?up|contato.*apresenta)/i.test(n))return false;return /(reuni[a-zA-Z\u00c0-\u017f]*|meeting|meet\b|videoconfer|diagn[o\u00f3]stic|apresenta[c\u00e7][a\u00e3]o|demo\b)/i.test(n)}
