const RC_ACCOUNT_IDS=new Set(['act_924330907101992','act_1091037777945129','act_592821485714185','act_1276540489807592','act_503018831703713','act_603210167832936','act_636965624958777','act_395648233280699','act_1785791218748439','act_3046150998923063','act_26731272769822436','act_27212100801787922','act_2597353157388197']);
// Funis oficiais: 78790 = SDR / Prospecção, 84566 = Closers / Vendas.
const RC_PROSPECTION_PIPELINE_ID='78790',RC_CLOSER_PIPELINE_ID='84566';
const RC_PIPELINE_IDS=new Set([RC_PROSPECTION_PIPELINE_ID,RC_CLOSER_PIPELINE_ID]);
function isReferenciaCapitalAccount(a){return RC_ACCOUNT_IDS.has(String(a?.id||''))}
function filterRcAccountIds(ids=[]){return [...new Set((ids||[]).map(String).filter(id=>RC_ACCOUNT_IDS.has(id)))]}
