function isReferenciaCapitalAdRaw(r){const text=scopeText([r?.campaign_name||'',r?.adset_name||'',r?.ad_name||''].join(' '));if(/segur|saude|amil|bradesco|plano de saude|corretor/.test(text))return false;const acc=scopeText(r?.account_name||'');return acc.includes('referencia capital')||text.includes('[rfc')}
function isReferenciaCapitalPipeline(p,stages=[]){return RC_PIPELINE_IDS.has(String(p?.id||''))}
async function getReferenciaPipelines(token){const[pipelines,stages]=await Promise.all([pipeAll('pipelines',{},token,20),pipeAll('stages',{},token,30).catch(()=>[])]);return pipelines.filter(p=>{const ps=stages.filter(s=>String(s.pipeline_id??s.pipeline?.id??s.pipelineId??'')===String(p.id));return isReferenciaCapitalPipeline(p,ps)}).map(p=>({id:String(p.id),name:String(p.name||''),stages:stages.filter(s=>String(s.pipeline_id??s.pipeline?.id??s.pipelineId??'')===String(p.id)).map(s=>({id:String(s.id),name:String(s.name||'')}))}))}
