function addAdStat(map,id,patch){if(!map[id])map[id]={opportunities:0,meetings:0,noShows:0,wins:0,revenue:0,attributed:true};for(const[k,v]of Object.entries(patch))map[id][k]=(map[id][k]||0)+v}
function addOwnerAdStat(map,adId,ownerIdValue,patch){const aid=String(adId||''),oid=String(ownerIdValue||'');if(!aid||!oid)return;if(!map[aid])map[aid]={};if(!map[aid][oid])map[aid][oid]={opportunities:0,meetings:0,noShows:0,wins:0,revenue:0};for(const[k,v]of Object.entries(patch))map[aid][oid][k]=(map[aid][oid][k]||0)+Number(v||0)}
function deepFindValue(obj,patterns){let found='';function walk(v){if(found||v==null)return;if(Array.isArray(v)){for(const x of v)walk(x);return}if(typeof v==='object'){for(const[k,x]of Object.entries(v)){if(patterns.some(r=>r.test(String(k)))&&x!=null&&['string','number'].includes(typeof x)){found=String(x);return}walk(x)}}}walk(obj);return found}
function firstContact(person,kind){const keys=kind==='email'?['contactEmails','contact_emails','emails','email']:['contactPhones','contact_phones','phones','phone','mobile','whatsapp'];for(const k of keys){const v=person?.[k];if(Array.isArray(v)&&v.length){const x=v[0];return String(x?.email||x?.phone||x?.value||x?.number||'')}if(typeof v==='string'&&v)return v}return''}
