    const [adRows,campaignDaily]=await Promise.all([getArchiveAdDailyInsights(id,since3,until,cfg),getDailyInsights(id,since30,until,cfg)]);
    out.adDays+=await saveMetaAdDays(env,(adRows||[]).filter(isReferenciaCapitalAdRaw).map(normalizeAd));
