// ---------- Ficha do lead pelo Cloudflare (PipeRun ao vivo + referências do D1) ----------
async function rcRefs(env){const r=(await env.DB.prepare("SELECT kind,id,name,extra_json FROM crm_ref WHERE kind IN ('stage','user','lostReason')").all()).results||[],m={stage:new Map(),user:new Map(),lost:new Map()};for(const x of r){let e={};try{e=JSON.parse(x.extra_json||'{}')}catch{}(x.kind==='stage'?m.stage:x.kind==='user'?m.user:m.lost).set(String(x.id),{name:x.name,...e})}return m}
async function rcDealCloud(env,id){
  if(!/^[0-9]+$/.test(id))return{error:'Negócio inválido.'};
  const token=await getPipeToken(env),R=await rcRefs(env),rows=j=>Array.isArray(j?.data)?j.data:Array.isArray(j?.data?.data)?j.data.data:(j?.data&&typeof j.data==='object'?[j.data]:[]);
  let d=await env.DB.prepare('SELECT * FROM crm_deal WHERE id=?').bind(id).first();
  if(!d){const raw=rows(await pipeGet('deals/'+id,{},token))[0];if(!raw||!['78790','84566'].includes(String(raw.pipeline_id)))return{error:'Negócio não encontrado nos funis da Referência.'};d={id:String(raw.id),title:raw.title,pipeline_id:String(raw.pipeline_id),stage_id:String(raw.stage_id),started_in_stage_id:String(raw.started_in_stage_id||''),status:Number(raw.status||0),owner_id:String(raw.owner_id||''),person_id:String(raw.person_id||''),lost_reason_id:String(raw.lost_reason_id||''),value:raw.value,created_at:raw.created_at,closed_at:raw.closed_at,updated_at:raw.updated_at}}
  const by=async res=>{try{return rows(await pipeGet(res,{deal_id:id,show:200},token)).filter(x=>String(x.deal_id)===id)}catch{return[]}};
  const [notes,history,calls]=await Promise.all([by('notes'),by('stageHistories'),by('calls')]);
  const related=d.person_id?((await env.DB.prepare('SELECT id,pipeline_id,stage_id,status,owner_id,created_at,closed_at,lost_reason_id FROM crm_deal WHERE person_id=? AND id<>?').bind(String(d.person_id),id).all()).results||[]):[];
  const ids=[id,...related.map(r=>String(r.id))],meetings=(await env.DB.prepare(`SELECT * FROM crm_activity WHERE deal_id IN (${ids.map(()=>'?').join(',')}) ORDER BY start_at`).bind(...ids).all()).results||[];
  const real=((await env.META_CONFIG.get('rc_loss_real','json'))||{})[id]||null;
  const first=[...R.stage.entries()].filter(([,s])=>s.pipeline_id===String(d.pipeline_id)).sort((a,b)=>a[1].order-b[1].order)[0]?.[0];
  return{...buildDetail(d,R,{notes,history,calls},meetings,related,real,first),source:'cloud'};
}
async function rcSaveLoss(env,b){const id=String(b?.deal_id||''),reason=String(b?.reason||'').slice(0,120);if(!/^[0-9]+$/.test(id)||![...REAL_LOSS.SDR,...REAL_LOSS.CLOSER].includes(reason))return{error:'Motivo inválido.'};const map=(await env.META_CONFIG.get('rc_loss_real','json'))||{};map[id]={reason,note:String(b?.note||'').slice(0,1000),at:new Date(Date.now()-3*3600000).toISOString().replace('T',' ').slice(0,19)};await env.META_CONFIG.put('rc_loss_real',JSON.stringify(map));return{ok:true}}

// ---------- Rastreador das páginas (público: /t.js e /t/c) ----------
const TRACK_CORS={'access-control-allow-origin':'*','access-control-allow-methods':'POST,OPTIONS','access-control-allow-headers':'content-type'};
async function trackCollect(req,env){
  const txt=await req.text();if(txt.length>200000)return new Response('',{status:413,headers:TRACK_CORS});
  let b;try{b=JSON.parse(txt)}catch{return new Response('',{status:400,headers:TRACK_CORS})}
  const s=v=>v==null?'':String(v),sid=s(b.sid).slice(0,40);if(!/^[a-z0-9]{8,40}$/.test(sid))return new Response('',{status:400,headers:TRACK_CORS});
  const cf=req.cf||{},q=b.q||{},ua=s(req.headers.get('user-agent')).slice(0,300),device=/Mobi|Android|iPhone/i.test(ua)?'mobile':/iPad|Tablet/i.test(ua)?'tablet':'desktop';
  const now=new Date(Date.now()-3*3600000).toISOString().replace('T',' ').slice(0,19),lead=b.lead||{};
  const clicks=JSON.stringify(Array.isArray(b.clicks)?b.clicks.slice(0,150):[]).slice(0,60000);
  await env.DB.prepare(`INSERT INTO rc_track(sid,vid,host,path,url,ref,q_json,first_json,ad_id,utm_source,utm_campaign,utm_content,fbclid,ua,device,w,h,lang,ip,country,region,city,lat,lon,tz,started_at,last_at,dur,scroll,clicks_json,form,email,phone,name,last_kind)
    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT(sid) DO UPDATE SET last_at=excluded.last_at,dur=MAX(rc_track.dur,excluded.dur),scroll=MAX(rc_track.scroll,excluded.scroll),clicks_json=excluded.clicks_json,form=MAX(rc_track.form,excluded.form),
    email=COALESCE(NULLIF(excluded.email,''),rc_track.email),phone=COALESCE(NULLIF(excluded.phone,''),rc_track.phone),name=COALESCE(NULLIF(excluded.name,''),rc_track.name),last_kind=excluded.last_kind`)
    .bind(sid,s(b.vid).slice(0,40),s(b.host).slice(0,120),s(b.path).slice(0,300),s(b.url).slice(0,1000),s(b.ref).slice(0,500),JSON.stringify(q).slice(0,2000),s(b.first).slice(0,2000),s(q.ad_id).slice(0,30),s(q.utm_source).slice(0,120),s(q.utm_campaign).slice(0,300),s(q.utm_content).slice(0,300),s(q.fbclid).slice(0,300),
      ua,device,Number(b.w)||0,Number(b.h)||0,s(b.lang).slice(0,20),s(req.headers.get('cf-connecting-ip')).slice(0,60),s(cf.country),s(cf.region),s(cf.city),Number(cf.latitude)||null,Number(cf.longitude)||null,s(cf.timezone),
      now,now,Number(b.dur)||0,Math.min(100,Number(b.scroll)||0),clicks,Number(b.form)||0,s(lead.email).slice(0,120),s(lead.phone).slice(0,30),s(lead.name).slice(0,80),s(b.k).slice(0,10)).run();
  return new Response('',{status:204,headers:TRACK_CORS});
}
// ---------- Login do painel (senha em wrangler secret PANEL_PASSWORD; sessão assinada por 30 dias) ----------
async function panelSig(env,exp){const k=await crypto.subtle.importKey('raw',new TextEncoder().encode('rc-panel:'+String(env.PANEL_PASSWORD||'')),{name:'HMAC',hash:'SHA-256'},false,['sign']);return btoa(String.fromCharCode(...new Uint8Array(await crypto.subtle.sign('HMAC',k,new TextEncoder().encode(String(exp)))))).replace(/[+/=]/g,'')}
async function panelSession(req,env){if(!env.PANEL_PASSWORD)return true;const m=(req.headers.get('cookie')||'').match(/(?:^|;[ ]*)rc_s=([0-9]+)[.]([A-Za-z0-9]+)/);if(!m||Number(m[1])<Date.now())return false;return m[2]===await panelSig(env,m[1])}
function loginPage(msg=''){return new Response(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Referência Capital</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#052c26;color:#f5f6f2;font-family:Segoe UI,Arial,sans-serif;padding:16px}form{background:#0a3b32;border:1px solid rgba(221,196,113,.25);border-radius:16px;padding:28px;width:min(360px,100%);display:grid;gap:14px}h1{margin:0;font-size:20px}p{margin:0;color:#9fb4ad;font-size:14px}input{padding:11px;border-radius:10px;border:1px solid rgba(221,196,113,.3);background:#052c26;color:#f5f6f2;font-size:15px}button{padding:11px;border:0;border-radius:10px;background:#e8c46c;color:#13281f;font-weight:700;font-size:15px;cursor:pointer}.e{color:#ff8e87}</style></head><body><form method="post" action="/login"><h1>Referência Capital</h1><p>Growth Funnel OS — acesso restrito.</p><input type="password" name="senha" placeholder="Senha" autofocus required aria-label="Senha">${msg?`<p class="e">${msg}</p>`:''}<button>Entrar</button></form></body></html>`,{status:msg?401:200,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store'}})}
export default{async fetch(request,env){const url=new URL(request.url);
  if(url.pathname==='/login'&&request.method==='POST'){const f=await request.formData().catch(()=>null),p=String(f?.get('senha')||'');if(!env.PANEL_PASSWORD||p.trim()!==String(env.PANEL_PASSWORD).trim()){await new Promise(r=>setTimeout(r,800));return loginPage('Senha incorreta.')}const exp=Date.now()+30*86400000;return new Response(null,{status:303,headers:{location:'/','set-cookie':`rc_s=${exp}.${await panelSig(env,exp)}; Path=/; Max-Age=2592000; HttpOnly; Secure; SameSite=Lax`}})}
  if(url.pathname==='/t/c'){if(request.method==='OPTIONS')return new Response(null,{status:204,headers:TRACK_CORS});if(request.method==='POST')return trackCollect(request,env).catch(()=>new Response('',{status:500,headers:TRACK_CORS}))}
  if(url.pathname==='/t.js'){const a=await env.ASSETS.fetch(request);return new Response(a.body,{status:a.status,headers:{'content-type':'application/javascript; charset=utf-8','cache-control':'public, max-age=3600','access-control-allow-origin':'*'}})}
  if(url.pathname==='/logout')return new Response(null,{status:303,headers:{location:'/','set-cookie':'rc_s=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax'}});
  const machine=url.pathname.startsWith('/api/archive/');
  if(!machine&&!(await panelSession(request,env))&&!(request.headers.get('x-archive-signature')&&await archiveAuthorized(request,url)))return url.pathname.startsWith('/api/')?json({error:'Faça login no painel.'},401):loginPage();
  if(url.pathname.startsWith('/api/'))return handleApi(request,env,url);return env.ASSETS.fetch(request)},async scheduled(){/* Desligado: o PC busca Meta/PipeRun e envia ao Cloudflare (/api/archive/push). */}};
